JavaScript:
let angka = [1, 2, 3];
const ul = document.querySelector("#u");
function render() {
  ul.replaceChildren(...angka.map((n) => {
    const li = document.createElement("li");
    li.textContent = n * 10;
    return li;
  }));
}
render();
angka = angka.filter((n) => n !== 2);
render();
console.log(ul.textContent);

